/* Local purchase walkthrough. No payment credentials, charges, email or real tickets. */
(() => {
 const M=window.noodoCheckoutModel,I=window.noodoEventIdentity,E=I.escape;
 const root=document.getElementById('checkout'),storeKey='noodo-purchase-demo-v1';
 const read=()=>{try{return JSON.parse(sessionStorage.getItem(storeKey))||{drafts:{},orders:[]};}catch{return {drafts:{},orders:[]};}};
 let data=read();if(!data.drafts||!Array.isArray(data.orders))data={drafts:{},orders:[]};
 function save(){try{sessionStorage.setItem(storeKey,JSON.stringify(data));return true;}catch{message('No se pudo guardar esta prueba. Permite el almacenamiento de sesión para continuar.');return false;}}
 function message(text){document.getElementById('purchase-message').textContent=text;}
 function go(params,replace=false){const url=new URL('checkout.html',location.href);Object.entries(params).forEach(([k,v])=>url.searchParams.set(k,v));history[replace?'replaceState':'pushState']({},'',url);render();root.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
 const date=e=>new Intl.DateTimeFormat('es-CO',{dateStyle:'long',timeZone:'UTC'}).format(new Date(e.dateISO+'T12:00:00Z'));
 const href=e=>'event.html?event='+e.code;
 function draft(e){return data.drafts[e.code]||(data.drafts[e.code]={quantities:{general:1},buyer:{},method:'card',consent:false});}
 const statuses={pending:'Pendiente',approved:'Aprobado',declined:'Rechazado',cancelled:'Cancelado',expired:'Vencido',error:'Error'};
 function top(e,step){return `<div class="checkout-top"><a class="quiet" href="${href(e)}">← Volver al evento</a><ol class="steps" aria-label="Pasos de compra">${['Boletas','Tus datos','Pago'].map((s,i)=>`<li ${step===i+1?'aria-current="step"':''}><b>${i+1}</b>${s}</li>`).join('')}</ol></div>`;}
 function summary(e,q){let quote;try{quote=M.quote(e,q);}catch{quote={lines:[],total:0,quantity:0};}return `<aside class="order-summary" aria-label="Resumen de compra"><div class="summary-event"><img src="${E(e.image)}" alt="Flyer de ${E(e.name)}"><div><h2>${E(e.name)}</h2><p>${E(date(e))} · ${E(e.time)}<br>${E(e.place)}, Cali</p><small>${e.code}</small></div></div><div class="summary-lines">${quote.lines.map(l=>`<div class="summary-line"><span>${l.quantity} × ${E(l.name)}</span><strong>${M.money(l.subtotal)}</strong></div>`).join('')}<div class="summary-line"><span>Servicio en esta prueba</span><strong>${M.money(0)}</strong></div><div class="summary-line total"><span>Total</span><strong>${M.money(quote.total)}</strong></div><p class="summary-note">${quote.quantity} ${quote.quantity===1?'boleta':'boletas'} · Precios de muestra en pesos colombianos. Sin cargos adicionales en esta prueba.</p></div><div class="summary-security">No se solicitan datos financieros en NOODO.</div></aside>`;}
 function layout(e,step,body,q){return top(e,step)+`<div class="checkout-layout"><section class="checkout-content">${body}</section>${summary(e,q)}</div>`;}
 function title(kicker,title,copy){return `<span class="eyebrow">${kicker}</span><h1>${title}</h1><p class="intro">${copy}</p>`;}
 function selectTickets(e,d){
  root.innerHTML=layout(e,1,title('Tu próximo encuentro','Elige tus boletas','Un lugar para escuchar, compartir y estar cerca. Elige tu localidad y cuántas boletas necesitas.')+`<section class="panel"><div class="section-kicker"><span>01</span><h2>Localidades</h2></div>${e.localities.map(l=>`<div class="locality"><div><h3>${E(l.name)}</h3><p>${E(l.description)}</p><span class="availability">${l.available} disponibles · muestra</span><strong>${l.price?M.money(l.price):'Gratis'}</strong></div><div class="quantity"><button type="button" data-qty="${l.id}" data-delta="-1" aria-label="Quitar boleta ${E(l.name)}" ${(d.quantities[l.id]||0)===0?'disabled':''}>−</button><input type="number" readonly tabindex="-1" aria-label="Cantidad ${E(l.name)}" value="${d.quantities[l.id]||0}"><button type="button" data-qty="${l.id}" data-delta="1" aria-label="Agregar boleta ${E(l.name)}" ${Object.values(d.quantities).reduce((a,b)=>a+b,0)>=6||(d.quantities[l.id]||0)>=l.available?'disabled':''}>+</button></div></div>`).join('')}<p class="micro">Máximo 6 boletas por pedido. Localidades sin numeración.</p></section><p id="form-error" class="form-error" role="alert"></p><button type="button" class="btn primary block" data-next>Continuar con mis datos →</button><p class="micro">Puedes comprar como invitado. No necesitas crear una cuenta.</p>`,d.quantities);
  root.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{const id=b.dataset.qty,l=e.localities.find(l=>l.id===id),n=(d.quantities[id]||0)+Number(b.dataset.delta),count=Object.values(d.quantities).reduce((a,b)=>a+b,0)+Number(b.dataset.delta);if(n>=0&&n<=l.available&&count<=6){d.quantities[id]=n;d.consent=false;save();selectTickets(e,d);root.querySelector(`[data-qty="${id}"][data-delta="${b.dataset.delta}"]`)?.focus({preventScroll:true});}});
  root.querySelector('[data-next]').onclick=()=>{try{M.quote(e,d.quantities);if(save())go({event:e.code,step:'datos'});}catch(err){root.querySelector('#form-error').textContent=err.message;}};
 }
 function buyerValid(d){const b=d.buyer;return typeof b.name==='string'&&b.name.trim().length>=2&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(b.email||'')&&b.email.toLowerCase()===String(b.confirm||'').toLowerCase()&&/^[0-9+ ()-]{7,20}$/.test(b.phone||'')&&d.consent===true;}
 function buyerForm(e,d){
  const b=d.buyer;
  root.innerHTML=layout(e,2,title('Casi estamos','¿Quién viene al evento?','Estos datos identifican al comprador. En esta prueba no se enviarán correos.')+`<form id="buyer-form"><section class="panel"><div class="section-kicker"><span>02</span><h2>Datos del comprador</h2></div><div class="field-grid"><label class="field full">Nombre y apellidos<input name="name" autocomplete="name" required minlength="2" maxlength="100" value="${E(b.name)}" placeholder="Como aparece en tu documento"></label><label class="field">Correo electrónico<input name="email" type="email" autocomplete="email" required maxlength="150" value="${E(b.email)}" placeholder="nombre@correo.com"></label><label class="field">Confirma tu correo<input name="confirm" type="email" autocomplete="off" required maxlength="150" value="${E(b.confirm)}" placeholder="Escríbelo de nuevo"></label><label class="field full">Celular<input name="phone" type="tel" autocomplete="tel" required pattern="[0-9+ ()\u002d]{7,20}" maxlength="20" value="${E(b.phone)}" placeholder="+57 300 000 0000"><small>Incluye el indicativo si tu número es de otro país.</small></label></div><label class="check-field"><input name="consent" type="checkbox" required ${d.consent?'checked':''}><span>He revisado las <button type="button" data-terms>condiciones de esta compra de prueba</button>.</span></label></section><p class="form-error" id="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-back>Volver</button><button class="btn primary" type="submit">Continuar al pago →</button></div></form>`,d.quantities);
  const form=root.querySelector('form');form.addEventListener('input',()=>{d.buyer=Object.fromEntries(new FormData(form));d.consent=form.elements.consent.checked;form.elements.confirm.setCustomValidity('');save();});
  form.onsubmit=ev=>{ev.preventDefault();const values=Object.fromEntries(new FormData(form));d.buyer=values;d.consent=form.elements.consent.checked;if(values.email.toLowerCase()!==values.confirm.toLowerCase()){form.elements.confirm.setCustomValidity('Los correos no coinciden.');form.elements.confirm.reportValidity();return;}if(!buyerValid(d)){root.querySelector('#form-error').textContent='Revisa tus datos y las condiciones antes de continuar.';return;}if(save())go({event:e.code,step:'pago'});};
  root.querySelector('[data-back]').onclick=()=>go({event:e.code,step:'boletas'});
 }
 function pay(e,d){
  const quote=M.quote(e,d.quantities),free=quote.total===0;
  root.innerHTML=layout(e,3,title('El último paso',free?'Confirma tus entradas':'¿Cómo quieres pagar?',free?'Este evento es gratuito. No necesitas un medio de pago.':'Elige tu medio de pago. La autorización se completa en la pasarela.')+`<section class="panel"><div class="buyer-review"><div><strong>${E(d.buyer.name)}</strong><small>${E(d.buyer.email)}<br>${E(d.buyer.phone)}</small></div><button class="quiet" data-edit>Editar</button></div>${free?'<div class="callout">Entrada gratuita · Total $0 COP</div>':`<fieldset class="payment-methods"><legend>Medio de pago</legend>${M.methods.map(m=>`<label class="payment-option"><input type="radio" name="payment-method" value="${m.id}" ${d.method===m.id?'checked':''}><span class="payment-mark" aria-hidden="true">${m.mark}</span><span><strong>${m.name}</strong><small>${m.detail}</small></span></label>`).join('')}</fieldset>`}<p class="micro">${free?'Se generará una entrada de muestra.':'Medios previstos para Colombia. Su activación depende de la cuenta del comercio y la pasarela.'}</p></section><div class="callout">Revisa tu evento, localidad, cantidad y total. Esta compra es una simulación y no generará cobros.</div><p id="form-error" class="form-error" role="alert"></p><div class="form-actions"><button class="btn" data-back>Volver</button><button class="btn primary" data-pay>${free?'Confirmar entrada de prueba':'Continuar con '+(M.methods.find(m=>m.id===d.method)?.short||'el pago')} →</button></div>`,d.quantities);
  root.querySelector('[data-edit]').onclick=()=>go({event:e.code,step:'datos'});root.querySelector('[data-back]').onclick=()=>go({event:e.code,step:'datos'});
  root.querySelectorAll('[name=payment-method]').forEach(r=>r.onchange=()=>{d.method=r.value;save();root.querySelector('[data-pay]').textContent='Continuar con '+M.methods.find(m=>m.id===r.value).short+' →';});
  root.querySelector('[data-pay]').onclick=()=>{try{
   // Reuse an unresolved attempt: returning/back/refresh must not create a duplicate.
   const pending=data.orders.find(o=>o.eventCode===e.code&&o.status==='pending'&&o.expiresAt>Date.now());
   if(pending){go({event:e.code,order:pending.id,step:'resultado'});return;}
   let order=M.createOrder(e,d.quantities,d.method);if(free)order=M.transition(order,'approved',e);data.orders.push(order);if(save())go({event:e.code,order:order.id,step:free?'resultado':'pasarela'});
  }catch(err){root.querySelector('#form-error').textContent=err.message;}};
 }
 function finish(order,state,e){try{const next=M.transition(order,state,e);data.orders=data.orders.map(o=>o.id===order.id?next:o);if(save())go({event:e.code,order:order.id,step:'resultado'});}catch(err){message(err.message);}}
 function simulator(order,e){return `<details class="simulator"><summary>Probar otros resultados del pago</summary><p class="micro">Controles de demostración. No se contacta a un banco ni se procesa dinero.</p><div class="form-actions"><button class="btn" data-outcome="pending">Pendiente</button><button class="btn" data-outcome="declined">Rechazado</button><button class="btn" data-outcome="cancelled">Cancelado</button><button class="btn" data-outcome="expired">Vencido</button><button class="btn" data-outcome="error">Error de conexión</button></div></details>`;}
 function wireOutcomes(order,e){root.querySelectorAll('[data-outcome]').forEach(b=>b.onclick=()=>b.dataset.outcome==='pending'?go({event:e.code,order:order.id,step:'resultado'}):finish(order,b.dataset.outcome,e));}
 function provider(e,order){
  const method=M.methods.find(m=>m.id===order.method);if(!method){go({event:e.code,order:order.id,step:'resultado'},true);return;}
  const card=order.method==='card',cash=order.method==='cash';
  root.innerHTML=layout(e,3,title('Autorización · '+method.short,'Completa tu pago','Vista previa del paso que se realiza en la pasarela. Aquí no se solicitan credenciales reales.')+`<section class="panel"><div class="section-kicker"><span>${method.mark}</span><h2>${method.name}</h2></div><p class="intro">${method.instruction}</p>${card?'<div class="provider-card"><div class="provider-heading"><strong>Tarjeta de ejemplo</strong><small>NOODO · PRUEBA</small></div><div class="number">•••• •••• •••• 4242</div><small>Vista de campos alojados en la pasarela</small></div><div class="field-grid"><label class="field full">Nombre en la tarjeta<input value="PERSONA DE PRUEBA" readonly aria-readonly="true"></label><label class="field full">Número de tarjeta<input value="•••• •••• •••• 4242" readonly aria-readonly="true"></label><label class="field">Vencimiento<input value="12 / 29" readonly aria-readonly="true"></label><label class="field">Código de seguridad<input value="•••" readonly aria-readonly="true"></label></div><p class="micro">Campos de muestra bloqueados. Las cuotas y la verificación del banco se completarán en la pasarela habilitada.</p>':cash?`<p class="micro">Referencia ilustrativa; no uses este código para pagar.</p><code class="reference">${E(order.id)}</code><p class="micro">Vence: ${new Date(order.expiresAt).toLocaleString('es-CO',{timeZone:'America/Bogota'})} · Colombia</p>`:`<ol class="instructions"><li>Continúa al servicio de ${method.short}.</li><li>Autoriza el valor de ${M.money(order.total)}.</li><li>Regresa para consultar el resultado.</li></ol>`}<button class="btn primary block" ${card?'data-verify':`data-outcome="${cash?'pending':'approved'}"`}>${card?'Simular verificación del banco':cash?'Ver pago pendiente de prueba':'Simular autorización aprobada'}</button><button class="quiet" data-outcome="cancelled">Cancelar intento de prueba</button></section>${simulator(order,e)}`,order.quantities);
  wireOutcomes(order,e);
  root.querySelector('[data-verify]')?.addEventListener('click',()=>go({event:e.code,order:order.id,step:'verificacion'}));
 }
 function verification(e,order){
  root.innerHTML=layout(e,3,title('Verificación de tarjeta','Confirma con tu banco','Algunas tarjetas necesitan una autorización adicional. Este paso representa la verificación del emisor.')+`<section class="panel"><div class="result-icon" aria-hidden="true">✓</div><h2>Autoriza ${M.money(order.total)}</h2><p class="intro">Sigue las indicaciones de tu banco en su página o aplicación. NOODO no solicita claves bancarias ni códigos de un solo uso.</p><div class="callout">Simulación de verificación 3D Secure. No se contacta a ningún banco y no necesitas ingresar un código.</div><button class="btn primary block" data-outcome="approved">Simular verificación aprobada</button><button class="quiet" data-outcome="cancelled">Cancelar verificación de prueba</button></section>${simulator(order,e)}`,order.quantities);
  wireOutcomes(order,e);
 }
 function result(e,order){
  const content={approved:['✓','¡Ya tienes un lugar!','Tu compra de prueba fue aprobada. Puedes consultar y descargar las boletas de muestra. No se ha enviado ningún correo.'],pending:['◷','Estamos esperando tu pago','Todavía no hay un pago confirmado. No se han emitido boletas; evita iniciar otro pago mientras este siga pendiente.'],declined:['×','El pago no fue aprobado','Este intento fue rechazado. Revisa el medio de pago o elige otro para volver a intentar.'],cancelled:['↩','Pago cancelado','El intento terminó sin una compra confirmada. Puedes volver a elegir cómo pagar.'],expired:['◷','El intento ha vencido','El plazo de esta prueba terminó. Vuelve a revisar la disponibilidad y crea un nuevo intento.'],error:['!','No pudimos completar el pago','Esta prueba representa un error de conexión. En una compra real, consulta el estado antes de volver a pagar.']}[order.status];
  root.innerHTML=layout(e,3,`<div class="result-icon ${order.status}" aria-hidden="true">${content[0]}</div>`+title('Pedido de prueba',content[1],content[2])+`<section class="panel"><h2>Detalle del pedido</h2><dl class="result-meta"><div><dt>Estado</dt><dd>${statuses[order.status]} · Prueba</dd></div><div><dt>Referencia</dt><dd>${E(order.id)}</dd></div><div><dt>Medio</dt><dd>${M.methods.find(m=>m.id===order.method)?.name||'Entrada gratuita'}</dd></div><div><dt>Total</dt><dd>${M.money(order.total)}</dd></div></dl></section><div class="form-actions">${order.status==='approved'?'<button class="btn primary" data-tickets>Ver mis boletas →</button>':order.status==='pending'?'<button class="btn primary" data-refresh>Consultar estado</button><button class="btn" data-resume>Continuar pago</button>':'<button class="btn primary" data-retry>Intentar de nuevo</button>'}<a class="btn" href="listen.html?section=radar">Explorar eventos</a></div>${order.status==='pending'?`<p class="micro">El estado se conserva al recargar. En esta prueba, usa los controles para simular la respuesta.</p><details class="simulator"><summary>Simular respuesta de la pasarela</summary><div class="form-actions"><button class="btn" data-outcome="approved">Pago aprobado</button><button class="btn" data-outcome="declined">Pago rechazado</button><button class="btn" data-outcome="cancelled">Cancelar</button><button class="btn" data-outcome="expired">Vencer intento</button></div></details>`:''}`,order.quantities);
  if(order.status==='approved')root.querySelector('[data-tickets]').onclick=()=>go({event:e.code,order:order.id,step:'entradas'});
  if(order.status==='pending'){
   root.querySelector('[data-refresh]').onclick=()=>{render();message('Estado de prueba: pendiente. No se ha recibido una confirmación.');};
   root.querySelector('[data-resume]').onclick=()=>go({event:e.code,order:order.id,step:'pasarela'});wireOutcomes(order,e);
  }
  root.querySelector('[data-retry]')?.addEventListener('click',()=>go({event:e.code,step:order.status==='expired'?'boletas':'pago'}));
 }
 function ticketMarkup(e,order,t,index){return `<article class="admission-ticket"><img src="${E(new URL(e.image,location.href).href)}" alt="Flyer de ${E(e.name)}"><div class="ticket-copy"><span class="ticket-badge">MUESTRA · NO VÁLIDA PARA INGRESAR</span><h2>${E(e.name)}</h2><p>${E(date(e))} · ${E(e.time)}<br>${E(e.place)}, Cali</p><strong>${E(t.locality)} · Boleta ${index+1} de ${order.tickets.length}</strong><p>Sin numeración · ${M.money(t.price)}</p><span class="ticket-code">Evento ${e.code}<br>${E(t.id)}</span></div><div class="ticket-qr">${I.qr('NOODO:DEMO:TICKET:'+e.code+':'+t.id,'QR de boleta de muestra '+(index+1))}<small>QR único de muestra<br>No acredita pago ni acceso</small></div></article>`;}
 function tickets(e,order){
  if(order.status!=='approved'||!order.tickets.length){go({event:e.code,order:order.id,step:'resultado'},true);return;}
  root.innerHTML=`<div class="checkout-top"><button class="quiet" data-result>← Volver al pedido</button><a class="quiet" href="checkout.html?view=tickets">Todos mis pedidos</a></div>`+title('Un encuentro por vivir','Tus boletas','Guarda tus boletas de muestra o revisa su versión para imprimir. Cada una tiene un código y un QR independientes.')+`<div class="form-actions"><button class="btn primary" data-download>Descargar boletas</button><button class="btn" data-print>Imprimir / guardar PDF</button></div><div class="ticket-list">${order.tickets.map((t,i)=>ticketMarkup(e,order,t,i)).join('')}</div><p class="micro">Esta vista se conserva durante la sesión de este navegador. No se ha enviado por correo.</p>`;
  root.querySelector('[data-result]').onclick=()=>go({event:e.code,order:order.id,step:'resultado'});
  root.querySelector('[data-print]').onclick=()=>window.print();
  root.querySelector('[data-download]').onclick=()=>{const html='<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Boletas de muestra · NOODO</title><style>body{font:16px Arial;background:#110b1b;color:#fff;padding:24px}h1{font-size:24px}.admission-ticket{max-width:680px;margin:24px auto;padding:24px;border:1px solid #bbb;border-radius:18px;break-inside:avoid}.admission-ticket>img{display:none}.ticket-copy p{line-height:1.6}.ticket-code{display:block;overflow-wrap:anywhere;font:12px monospace;margin:20px 0}.ticket-badge{color:#c397f4}.ticket-qr svg{width:220px;height:220px}.ticket-qr small{display:block;margin-top:10px}@media print{body{background:white;color:black}}</style><h1>NOODO · Boletas de muestra</h1><p>No válidas para ingresar. No se realizó ningún cobro.</p>'+order.tickets.map((t,i)=>ticketMarkup(e,order,t,i)).join('')+'</html>';const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='NOODO-'+e.code+'-boletas-prueba.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Boletas de muestra descargadas. Puedes abrirlas sin conexión.');};
 }
 function historyView(){root.innerHTML=title('Tus encuentros','Mis boletas','Pedidos de prueba guardados durante esta sesión del navegador.')+`<div class="order-history">${data.orders.length?data.orders.slice().reverse().map(o=>{const e=I.find(o.eventCode);if(!e)return '';return `<article class="history-row"><div><span class="eyebrow">${statuses[o.status]} · PRUEBA</span><h2>${E(e.name)}</h2><p>${o.quantity} boletas · ${M.money(o.total)}<br>${E(o.id)}</p></div><button class="btn ${o.status==='approved'?'primary':''}" data-order="${E(o.id)}">${o.status==='approved'?'Ver boletas':'Ver estado'} →</button></article>`;}).join(''):'<div class="panel"><h2>Aún no tienes boletas</h2><p class="intro">Encuentra tu próximo evento y recorre la compra de prueba.</p><a class="btn primary" href="listen.html?section=radar">Explorar Radar</a></div>'}</div>`;root.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{const o=data.orders.find(o=>o.id===b.dataset.order);go({event:o.eventCode,order:o.id,step:o.status==='approved'?'entradas':'resultado'});});}
 function render(){
  document.getElementById('purchase-message').textContent='';data=read();if(!data.drafts||!Array.isArray(data.orders))data={drafts:{},orders:[]};
  const params=new URLSearchParams(location.search);if(params.get('view')==='tickets'){historyView();return;}
  const e=I.find(params.get('event'));if(!e){root.innerHTML=title('Radar','No encontramos este evento','Revisa el código o vuelve a explorar los eventos.')+'<a class="btn primary" href="listen.html?section=radar">Explorar Radar</a>';return;}
  document.title='Entradas · '+e.name+' · NOODO';const d=draft(e),step=params.get('step')||'boletas';
  if(params.has('quantities')){
   try{const quantities=JSON.parse(params.get('quantities'));M.quote(e,quantities);d.quantities=quantities;d.consent=false;save();}catch{message('La cantidad seleccionada no es válida. Revisa tus boletas.');}
   const clean=new URL(location.href);clean.searchParams.delete('quantities');history.replaceState({},'',clean);
  }
  const order=params.has('order')?data.orders.find(o=>o.id===params.get('order')&&o.eventCode===e.code&&o.demo===true):null;
  if(['pasarela','verificacion','resultado','entradas'].includes(step)){
   if(!order){root.innerHTML=title('Pedido no disponible','No encontramos este pedido','Los pedidos de prueba solo están disponibles en la sesión donde los creaste.')+`<a class="btn primary" href="checkout.html?event=${e.code}">Volver a las boletas</a>`;return;}
   if(order.status==='pending'&&Date.now()>order.expiresAt){finish(order,'expired',e);return;}
   if(step==='pasarela'&&order.status==='pending')provider(e,order);else if(step==='verificacion'&&order.status==='pending'&&order.method==='card')verification(e,order);else if(step==='entradas')tickets(e,order);else result(e,order);return;
  }
  if(step==='boletas'){selectTickets(e,d);return;}
  try{M.quote(e,d.quantities);}catch{go({event:e.code,step:'boletas'},true);return;}
  if(step==='datos'){buyerForm(e,d);return;}
  if(step==='pago'){if(!buyerValid(d)){go({event:e.code,step:'datos'},true);return;}pay(e,d);return;}
  go({event:e.code,step:'boletas'},true);
 }
 document.addEventListener('click',ev=>{if(ev.target.closest('[data-terms]'))document.getElementById('purchase-terms').showModal();});
 window.addEventListener('popstate',render);render();
})();
